#include "provisioning_service.h"
#include "cfg_service.h"
#include "esp_wifi.h"
#include "esp_netif.h"
#include "esp_http_server.h"
#include "esp_log.h"
#include "esp_random.h"
#include "cJSON.h"
#include "freertos/task.h"
#include "esp_timer.h"
#include "lwip/sockets.h"
#include "lwip/inet.h"
#include <string.h>
#include <stdio.h>
static const char *TAG="provisioning"; static httpd_handle_t s_http; static event_bus_t s_bus; static bool s_active;
static volatile bool s_scan_ready;
static wifi_ap_record_t s_scan_records[20]; static uint16_t s_scan_count;
static esp_timer_handle_t s_timeout_timer; static char s_old_ssid[33], s_old_pass[65]; static bool s_have_backup;
static void provision_timeout(void *arg){(void)arg;event_bus_publish(EV_PROVISIONING_TIMEOUT,NULL,0);}
static TaskHandle_t s_dns_task;
static void dns_task(void *arg){(void)arg; int fd=socket(AF_INET,SOCK_DGRAM,IPPROTO_UDP); if(fd<0){vTaskDelete(NULL);return;} struct sockaddr_in local={0};local.sin_family=AF_INET;local.sin_port=htons(53);local.sin_addr.s_addr=htonl(INADDR_ANY);bind(fd,(struct sockaddr*)&local,sizeof(local));uint8_t b[512];while(s_active){struct sockaddr_in peer;socklen_t plen=sizeof(peer);int n=recvfrom(fd,b,sizeof(b),0,(struct sockaddr*)&peer,&plen);if(n<12)continue;int q=12;while(q<n&&b[q])q+=b[q]+1;if(q+5>n)continue;q+=5;b[2]|=0x80;b[3]=0x80;b[6]=0;b[7]=1;b[8]=b[9]=b[10]=b[11]=0;int p=q;b[p++]=0xc0;b[p++]=0x0c;b[p++]=0;b[p++]=1;b[p++]=0;b[p++]=1;b[p++]=0;b[p++]=0;b[p++]=0;b[p++]=30;b[p++]=0;b[p++]=4;b[p++]=192;b[p++]=168;b[p++]=4;b[p++]=1;sendto(fd,b,p,0,(struct sockaddr*)&peer,plen);}shutdown(fd,SHUT_RDWR);close(fd);s_dns_task=NULL;vTaskDelete(NULL);}
static esp_err_t captive_get(httpd_req_t *r){httpd_resp_set_status(r,"302 Found");httpd_resp_set_hdr(r,"Location","http://192.168.4.1/");return httpd_resp_sendstr(r,"Redirecting to YMOS Wi-Fi setup");}
static const char s_page[] = "<!doctype html><meta charset=utf-8><title>YMOS 配网</title><h2>YMOS Wi-Fi 配网</h2><button onclick=scan()>扫描 Wi-Fi</button><select id=ssid></select><br><input id=pass type=password placeholder=Wi-Fi密码><button onclick=save()>保存并连接</button><pre id=msg></pre><script>async function scan(){msg.textContent='扫描中...';await fetch('/api/scan');for(let i=0;i<20;i++){let a=await(await fetch('/api/scan/result')).json();if(a.ready){ssid.innerHTML=a.networks.map(x=>`<option>${x.ssid}</option>`).join('');msg.textContent='请选择 Wi-Fi 并输入密码';return}await new Promise(r=>setTimeout(r,500))}msg.textContent='扫描超时'}async function save(){let r=await fetch('/api/wifi',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ssid:ssid.value,password:pass.value})});msg.textContent=await r.text()}</script>";
static esp_err_t page_get(httpd_req_t *r){httpd_resp_set_type(r,"text/html; charset=utf-8");return httpd_resp_send(r,s_page,HTTPD_RESP_USE_STRLEN);}
static void scan_task(void *arg){(void)arg; wifi_scan_config_t c={0}; s_scan_ready=false; if(esp_wifi_scan_start(&c,true)==ESP_OK){s_scan_count=20;esp_wifi_scan_get_ap_records(&s_scan_count,s_scan_records);}else s_scan_count=0;s_scan_ready=true;vTaskDelete(NULL);}
static esp_err_t scan_get(httpd_req_t *r){if(s_scan_ready){xTaskCreate(scan_task,"wifi_scan",4096,NULL,3,NULL);s_scan_ready=false;return httpd_resp_sendstr(r,"{\"ready\":false,\"networks\":[]}");}return httpd_resp_sendstr(r,"{\"ready\":false,\"networks\":[]}");}
static esp_err_t scan_result_get(httpd_req_t *r){char out[2048];size_t p=0;bool first=true;p+=snprintf(out+p,sizeof(out)-p,"{\"ready\":%s,\"networks\":[",s_scan_ready?"true":"false");for(int i=0;i<s_scan_count&&p<sizeof(out);i++){if(!s_scan_records[i].ssid[0])continue;if(!first)p+=snprintf(out+p,sizeof(out)-p,",");first=false;p+=snprintf(out+p,sizeof(out)-p,"{\"ssid\":\"%s\",\"rssi\":%d,\"auth\":%d}",s_scan_records[i].ssid,s_scan_records[i].rssi,s_scan_records[i].authmode);}p+=snprintf(out+p,sizeof(out)-p,"]}");httpd_resp_set_type(r,"application/json");return httpd_resp_send(r,out,p);}
static esp_err_t info_get(httpd_req_t *r){char chip[20]={0},dev[64]={0},client[64]={0}; cfg_service_get_identity(chip,sizeof(chip),dev,sizeof(dev),client,sizeof(client)); char b[256]; snprintf(b,sizeof(b),"{\"device_id\":\"%s\",\"chip_id\":\"%s\",\"provisioned\":%s}",dev,chip,cfg_service_is_paired()?"true":"false"); httpd_resp_set_type(r,"application/json"); return httpd_resp_send(r,b,HTTPD_RESP_USE_STRLEN);}
static esp_err_t reset_post(httpd_req_t *r){cfg_service_erase(CFG_KEY_WIFI_SSID);cfg_service_erase(CFG_KEY_WIFI_PASSWORD);cfg_service_erase(CFG_KEY_PAIRED);httpd_resp_set_type(r,"application/json");return httpd_resp_sendstr(r,"{\"accepted\":true}");}
static esp_err_t wifi_post(httpd_req_t *r){ if(r->content_len<=0 || r->content_len>=256) return httpd_resp_send_err(r,HTTPD_400_BAD_REQUEST,"invalid body"); char body[256]={0}; int n=httpd_req_recv(r,body,r->content_len); if(n<=0)return httpd_resp_send_err(r,HTTPD_400_BAD_REQUEST,"read failed"); cJSON *root=cJSON_ParseWithLength(body,n); cJSON *s=root?cJSON_GetObjectItemCaseSensitive(root,"ssid"):NULL; cJSON *p=root?cJSON_GetObjectItemCaseSensitive(root,"password"):NULL; if(!cJSON_IsString(s)||!cJSON_IsString(p)||!s->valuestring[0]||strlen(s->valuestring)>32||strlen(p->valuestring)>64){if(root)cJSON_Delete(root);return httpd_resp_send_err(r,HTTPD_400_BAD_REQUEST,"invalid ssid/password");} cfg_get_wifi_credential(s_old_ssid,sizeof(s_old_ssid),s_old_pass,sizeof(s_old_pass)); s_have_backup=true; cfg_service_set_str(CFG_KEY_WIFI_SSID,s->valuestring); cfg_service_set_str(CFG_KEY_WIFI_PASSWORD,p->valuestring); cfg_service_mark_paired(); cJSON_Delete(root); httpd_resp_set_type(r,"application/json"); httpd_resp_sendstr(r,"{\"accepted\":true}"); event_bus_publish(EV_PROVISIONING_DONE,NULL,0); return ESP_OK;}
esp_err_t provisioning_service_init(event_bus_t bus){s_bus=bus;return ESP_OK;}
esp_err_t provisioning_service_start(void){if(s_active)return ESP_OK; esp_wifi_stop(); wifi_config_t ap={.ap={.channel=1,.max_connection=2,.authmode=WIFI_AUTH_WPA2_PSK}}; snprintf((char*)ap.ap.ssid,sizeof(ap.ap.ssid),"YMOS-%02X%02X",(unsigned char)esp_random(),(unsigned char)esp_random()); strcpy((char*)ap.ap.password,"ymos1234"); ap.ap.ssid_len=strlen((char*)ap.ap.ssid); esp_wifi_set_mode(WIFI_MODE_APSTA); esp_wifi_set_config(WIFI_IF_AP,&ap); esp_wifi_start(); s_active=true; xTaskCreate(dns_task,"captive_dns",3072,NULL,4,&s_dns_task); httpd_config_t c=HTTPD_DEFAULT_CONFIG(); if(httpd_start(&s_http,&c)!=ESP_OK)return ESP_FAIL; httpd_uri_t h={.uri="/",.method=HTTP_GET,.handler=page_get}; httpd_uri_t i={.uri="/api/info",.method=HTTP_GET,.handler=info_get}; httpd_uri_t q={.uri="/api/scan",.method=HTTP_GET,.handler=scan_get}; httpd_uri_t z={.uri="/api/scan/result",.method=HTTP_GET,.handler=scan_result_get}; httpd_uri_t w={.uri="/api/wifi",.method=HTTP_POST,.handler=wifi_post}; httpd_uri_t x={.uri="/api/reset",.method=HTTP_POST,.handler=reset_post}; httpd_uri_t cpt={.uri="/*",.method=HTTP_GET,.handler=captive_get}; httpd_register_uri_handler(s_http,&h); httpd_register_uri_handler(s_http,&i); httpd_register_uri_handler(s_http,&q); httpd_register_uri_handler(s_http,&z); httpd_register_uri_handler(s_http,&w); httpd_register_uri_handler(s_http,&x); httpd_register_uri_handler(s_http,&cpt); s_scan_ready=true; if(!s_timeout_timer){esp_timer_create_args_t a={.callback=provision_timeout,.name="prov_timeout"};esp_timer_create(&a,&s_timeout_timer);} esp_timer_start_once(s_timeout_timer,600000000); ESP_LOGI(TAG,"SoftAP provisioning started (password: ymos1234)"); return ESP_OK;}
esp_err_t provisioning_service_stop(void){if(!s_active)return ESP_OK; if(s_timeout_timer)esp_timer_stop(s_timeout_timer); s_active=false; if(s_http){httpd_stop(s_http);s_http=NULL;} if(s_dns_task){vTaskDelete(s_dns_task);s_dns_task=NULL;} esp_wifi_set_mode(WIFI_MODE_STA);return ESP_OK;}
bool provisioning_service_is_active(void){return s_active;}
void provisioning_service_rollback(void){if(!s_have_backup)return;cfg_service_set_str(CFG_KEY_WIFI_SSID,s_old_ssid);cfg_service_set_str(CFG_KEY_WIFI_PASSWORD,s_old_pass);s_have_backup=false;cfg_service_mark_paired();}

